<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';wajib_role(['ADMIN']);$result=mysqli_query($koneksi,"SELECT a.*,COALESCE(p.nama_lengkap,'-') nama_lengkap FROM audit_log a LEFT JOIN pengguna p ON a.id_pengguna=p.id_pengguna ORDER BY a.waktu DESC LIMIT 200");?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audit Log</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading"><span class="eyebrow">SISTEM</span><h1>Audit Log</h1><p>Riwayat aktivitas pengguna yang tercatat oleh sistem.</p></div><div class="dashboard-panel"><div class="table-responsive"><table class="data-table"><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aksi</th><th>Tabel</th><th>Record</th><th>IP</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($result)):?><tr><td><?=e($r['waktu'])?></td><td><?=e($r['nama_lengkap'])?></td><td><span class="badge"><?=e($r['aksi'])?></span></td><td><?=e($r['tabel_nama'])?></td><td><?=e($r['record_id']?:'-')?></td><td><?=e($r['ip_address']?:'-')?></td></tr><?php endwhile;?></tbody></table></div></div></main><script src="script.js"></script></body></html>